import{_ as s,o as n,c as p,a5 as i}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"76. 使用 gprof 进行分析","description":"The Little Book of C 中文版 — 76. 使用 gprof 进行分析","frontmatter":{"title":"76. 使用 gprof 进行分析","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","08-调试测试与 profiling","中文"],"description":"The Little Book of C 中文版 — 76. 使用 gprof 进行分析","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":76,"sidebarWeight":76,"alternateZh":"/posts/c教程/zh-CN/08-调试测试与 profiling/076-Profiling with gprof","alternateEn":"/posts/c教程/en-US/08-Debugging Testing Profiling/076-Profiling with gprof"},"headers":[],"relativePath":"posts/c教程/zh-CN/08-调试测试与 profiling/076-Profiling with gprof.md","filePath":"posts/c教程/zh-CN/08-调试测试与 profiling/076-Profiling with gprof.md","lastUpdated":1790163617000}'),e={name:"posts/c教程/zh-CN/08-调试测试与 profiling/076-Profiling with gprof.md"};function l(t,a,o,c,r,d){return n(),p("div",null,[...a[0]||(a[0]=[i(`<p>[English version](/posts/c教程/en-US/08-Debugging Testing Profiling/076-Profiling with gprof)</p><p>当您的程序可以运行但感觉很慢时，猜测是不够的，您需要进行测量。分析可以向您显示程序将时间花在哪些地方、哪些功能很热门以及哪些优化真正重要。</p><p>C 为您提供了很多控制权，但是没有分析的性能调整就像蒙住眼睛开车一样。这就是我们使用 GNU 分析器 gprof 的原因，它是一种测量代码在每个函数中花费多长时间的工具。</p><h4 id="步骤-1-什么是分析" tabindex="-1">步骤 1. 什么是分析？ <a class="header-anchor" href="#步骤-1-什么是分析" aria-label="Permalink to &quot;步骤 1. 什么是分析？&quot;">​</a></h4><p>分析是记录运行时统计信息的过程，例如：</p><ul><li>每个函数运行多少次。</li><li>每个函数使用多少CPU时间。</li><li>哪些函数调用哪些函数。</li></ul><p>它可以帮助您找到瓶颈、主导运行时的函数，并将优化重点放在此处。</p><h4 id="步骤-2-使用-gprof-启用分析" tabindex="-1">步骤 2. 使用 gprof 启用分析 <a class="header-anchor" href="#步骤-2-使用-gprof-启用分析" aria-label="Permalink to &quot;步骤 2. 使用 gprof 启用分析&quot;">​</a></h4><p>编译你的程序<code>-pg</code>启用分析挂钩的标志：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg main.c -o program</span></span></code></pre></div><p>正常运行程序：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./program</span></span></code></pre></div><p>完成后会生成一个名为<code>gmon.out</code>被创建。该文件包含运行时收集的执行数据。</p><p>生成报告：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gprof program gmon.out &gt; analysis.txt</span></span></code></pre></div><p>现已开放<code>analysis.txt</code>查看您的程序将时间花在哪里。</p><h4 id="步骤-3-示例程序" tabindex="-1">步骤 3. 示例程序 <a class="header-anchor" href="#步骤-3-示例程序" aria-label="Permalink to &quot;步骤 3. 示例程序&quot;">​</a></h4><p>这是一个演示分析的小示例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>void slow_function(void) {</span></span>
<span class="line"><span>    for (volatile long i = 0; i &lt; 50000000; i++);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void fast_function(void) {</span></span>
<span class="line"><span>    for (volatile long i = 0; i &lt; 5000000; i++);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    slow_function();</span></span>
<span class="line"><span>    fast_function();</span></span>
<span class="line"><span>    slow_function();</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg main.c -o profile_me</span></span>
<span class="line"><span>./profile_me</span></span>
<span class="line"><span>gprof profile_me gmon.out &gt; report.txt</span></span></code></pre></div><h4 id="步骤-4-阅读-gprof-报告" tabindex="-1">步骤 4. 阅读 gprof 报告 <a class="header-anchor" href="#步骤-4-阅读-gprof-报告" aria-label="Permalink to &quot;步骤 4. 阅读 gprof 报告&quot;">​</a></h4><p>该报告有两个关键部分：</p><ol><li>扁平轮廓</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>扁平轮廓：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>每个样本计为 0.01 秒。</span></span>
<span class="line"><span>% 累计自我总计</span></span>
<span class="line"><span>时间 秒 秒 呼叫 ms/呼叫 ms/呼叫名称</span></span>
<span class="line"><span>66.7 0.20 0.20 2 100.00 100.00 慢速函数</span></span>
<span class="line"><span>33.3 0.30 0.10 1 100.00 100.00 快速函数</span></span></code></pre></div><p>这告诉你：</p><p>-<code>slow_function()</code>占总时间的66%。 -<code>fast_function()</code>占了33%。</p><ol start="2"><li>调用图</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>index % time    self  children    called     name</span></span>
<span class="line"><span>                0.20    0.00       2/2       slow_function</span></span>
<span class="line"><span>                0.10    0.00       1/1       fast_function</span></span></code></pre></div><p>这显示了关系、哪些函数调用了哪些函数，以及它们之间的时间分配方式。</p><h4 id="步骤-5-分析多文件程序" tabindex="-1">步骤 5. 分析多文件程序 <a class="header-anchor" href="#步骤-5-分析多文件程序" aria-label="Permalink to &quot;步骤 5. 分析多文件程序&quot;">​</a></h4><p>当处理多个<code>.c</code>文件，只需编译每个文件<code>-pg</code>:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg -c foo.c</span></span>
<span class="line"><span>gcc -pg -c bar.c</span></span>
<span class="line"><span>gcc -pg foo.o bar.o -o app</span></span></code></pre></div><p>然后像以前一样运行并分析。</p><h4 id="步骤-6-忽略初始化或短期运行" tabindex="-1">步骤 6. 忽略初始化或短期运行 <a class="header-anchor" href="#步骤-6-忽略初始化或短期运行" aria-label="Permalink to &quot;步骤 6. 忽略初始化或短期运行&quot;">​</a></h4><p>分析最适合实际工作负载。避免分析微小的运行，因为初始化成本可能会主导并扭曲结果。</p><p>例如，如果您的程序总共只运行 20 毫秒，则 10 毫秒的启动延迟可能看起来很大。使用代表性输入和真实循环来获取有意义的数据。</p><h4 id="步骤-7-关注热点" tabindex="-1">步骤 7. 关注热点 <a class="header-anchor" href="#步骤-7-关注热点" aria-label="Permalink to &quot;步骤 7. 关注热点&quot;">​</a></h4><p>当您知道哪些函数在运行时占主导地位（通常是前 5%）时，您可以：</p><ul><li>手动内联它们。</li><li>使用更好的数据结构。</li><li>减少拨款。</li><li>简化内部循环。</li></ul><p>优化关乎精度，不要猜测你的代码哪里慢；让分析器证明这一点。</p><h4 id="步骤-8-将-gprof-与编译器优化相结合" tabindex="-1">步骤 8. 将 gprof 与编译器优化相结合 <a class="header-anchor" href="#步骤-8-将-gprof-与编译器优化相结合" aria-label="Permalink to &quot;步骤 8. 将 gprof 与编译器优化相结合&quot;">​</a></h4><p>比较添加优化标志之前和之后的性能：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg -O0 main.c -o slow</span></span>
<span class="line"><span>gcc -pg -O3 main.c -o fast</span></span></code></pre></div><p>然后运行两者并检查报告。您会看到时序分布发生巨大变化，有时甚至内联函数完全从配置文件中消失。</p><h4 id="步骤-9-可视化配置文件" tabindex="-1">步骤 9. 可视化配置文件 <a class="header-anchor" href="#步骤-9-可视化配置文件" aria-label="Permalink to &quot;步骤 9. 可视化配置文件&quot;">​</a></h4><p>您可以使用 gprof2dot 和 Graphviz 可视化 gprof 结果：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pip install gprof2dot</span></span>
<span class="line"><span>gprof program gmon.out | gprof2dot | dot -Tpng -o profile.png</span></span></code></pre></div><p>这会生成一个调用图图像，显示哪些函数占主导地位。箭头越粗，在那里花费的时间就越多。</p><h4 id="步骤-10-小代码-测量排序算法" tabindex="-1">步骤 10. 小代码：测量排序算法 <a class="header-anchor" href="#步骤-10-小代码-测量排序算法" aria-label="Permalink to &quot;步骤 10. 小代码：测量排序算法&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;time.h&gt;</span></span>
<span class="line"><span>#define N 100000</span></span>
<span class="line"><span>void bubble_sort(int *arr, int n) {</span></span>
<span class="line"><span>    for (int i = 0; i &lt; n - 1; i++)</span></span>
<span class="line"><span>        for (int j = 0; j &lt; n - i - 1; j++)</span></span>
<span class="line"><span>            if (arr[j] &gt; arr[j + 1]) {</span></span>
<span class="line"><span>                int tmp = arr[j];</span></span>
<span class="line"><span>                arr[j] = arr[j + 1];</span></span>
<span class="line"><span>                arr[j + 1] = tmp;</span></span>
<span class="line"><span>            }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>void fill_random(int *arr, int n) {</span></span>
<span class="line"><span>    for (int i = 0; i &lt; n; i++)</span></span>
<span class="line"><span>        arr[i] = rand() % 100000;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    int *arr = malloc(N * sizeof(int));</span></span>
<span class="line"><span>    fill_random(arr, N);</span></span>
<span class="line"><span>    bubble_sort(arr, N);</span></span>
<span class="line"><span>    free(arr);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译并运行：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc -pg main.c -O0 -o sort_profile</span></span>
<span class="line"><span>./sort_profile</span></span>
<span class="line"><span>gprof sort_profile gmon.out | head -n 20</span></span></code></pre></div><p>输出（摘录）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  %   cumulative   self              self     total</span></span>
<span class="line"><span> time   seconds   seconds    calls   ms/call  ms/call  name</span></span>
<span class="line"><span> 95.0      0.95     0.95        1   950.00   950.00  bubble_sort</span></span></code></pre></div><p>这告诉你 95% 的时间花在<code>bubble_sort()</code>，确认算法瓶颈。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>分析弥补了“感觉缓慢”和了解原因之间的差距。它可以帮助您：</p><ul><li>将优化工作集中在最重要的地方。</li><li>定量验证改进。</li><li>消除猜测。</li></ul><p>在性能工程中，测量每次都胜过直觉。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><ol><li>描述您自己的排序或搜索算法。</li><li>比较结果<code>-O0</code>,<code>-O2</code>， 和<code>-O3</code>.</li><li>分析多线程或 I/O 密集型程序。</li><li>可视化结果<code>gprof2dot</code>.</li><li>确定一个瓶颈并修复它，然后重新分析以查看差异。</li></ol><p>接下来，您将探索 C 中常见的未定义行为，这些无声错误可能会使您完美分析的程序意外崩溃。</p>`,63)])])}const u=s(e,[["render",l]]);export{h as __pageData,u as default};
